H.background();
const ord = Math.round(P.order);
const k = 0.5, A0 = 2.0, tEnd = 6;
const v = H.plot2d({ xMin: 0, xMax: tEnd, yMin: 0, yMax: 2.2 });
v.grid(); v.axes();
function conc(tt) {
  if (ord === 0) return Math.max(A0 - k * tt, 0);
  if (ord === 2) return 1 / (1 / A0 + k * tt);
  return A0 * Math.exp(-k * tt);
}
v.fn(x => conc(x), { color: H.colors.accent, width: 3 });
const sweep = (t % 6) / 6 * tEnd;
v.dot(sweep, conc(sweep), { r: 7, fill: H.colors.accent2 });
v.line(sweep, 0, sweep, conc(sweep), { color: H.colors.grid, width: 1, dash: [4, 4] });
const eqn = ord === 0 ? "[A] = [A]0 - k t" : ord === 1 ? "[A] = [A]0 e^(-k t)" : "1/[A] = 1/[A]0 + k t";
H.text("Integrated rate laws: [A] vs t", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("order " + ord + ":   " + eqn + "   (k=0.5, [A]0=2.0 M)", 24, 52, { color: H.colors.sub, size: 13 });
H.text("0th = straight drop  |  1st = exponential  |  2nd = slow tail", 24, 80, { color: H.colors.sub, size: 13 });
H.text("t = " + sweep.toFixed(2) + " s,  [A] = " + conc(sweep).toFixed(3) + " M", 24, 98, { color: H.colors.accent2, size: 13 });
